import * as T from './three.module.js';import {WEATHER,weatherType} from './weather.js?v=landscape13';
export function createSkyWeather({scene,camera,sun,renderer,mobile=false}){
 const hemi=scene.children.find(o=>o.isHemisphereLight),skyMat=new T.ShaderMaterial({side:T.BackSide,depthWrite:false,fog:false,uniforms:{top:{value:new T.Color('#4e9bd0')},horizon:{value:new T.Color('#d6e8df')}},vertexShader:'varying vec3 direction;void main(){direction=normalize(position);gl_Position=projectionMatrix*modelViewMatrix*vec4(position,1.0);}',fragmentShader:'uniform vec3 top;uniform vec3 horizon;varying vec3 direction;void main(){float h=smoothstep(-0.08,0.72,normalize(direction).y);gl_FragColor=vec4(mix(horizon,top,h),1.0);\n#include <tonemapping_fragment>\n#include <colorspace_fragment>\n}'});
 const sky=new T.Mesh(new T.SphereGeometry(1600,24,14),skyMat);sky.name='Gradient weather sky';sky.renderOrder=-100;sky.frustumCulled=false;scene.add(sky);scene.background=null;
 const cloudMat=new T.MeshBasicMaterial({color:'#f5f4e8',transparent:true,opacity:.75,depthWrite:false,fog:true});const clouds=new T.InstancedMesh(new T.SphereGeometry(1,10,7),cloudMat,mobile?48:96),dummy=new T.Object3D(),seed=[];clouds.name='Drifting cloud banks';clouds.frustumCulled=false;scene.add(clouds);
 for(let i=0;i<clouds.count;i++)seed.push({x:(i*67%560)-280,z:(i*97%560)-280,y:70+(i%5)*7,scale:8+i%7*1.4});
 const count=mobile?350:1100,rainGeo=new T.BufferGeometry(),positions=new Float32Array(count*3);for(let i=0;i<count;i++)positions.set([(i*17.3%70)-35,i*7.7%40,(i*23.1%70)-35],i*3);rainGeo.setAttribute('position',new T.BufferAttribute(positions,3));const rain=new T.Points(rainGeo,new T.PointsMaterial({color:'#cce3e5',size:.11,transparent:true,opacity:.65,depthWrite:false}));rain.name='Local weather precipitation';scene.add(rain);
 let elapsed=0,kind=null;const targets={top:new T.Color(),horizon:new T.Color(),fog:new T.Color()};
 return {sky,clouds,rain,update(dt,state,focus){elapsed+=dt;const type=weatherType(state),w=WEATHER[type];if(type!==kind){kind=type;targets.top.set(w.top);targets.horizon.set(w.horizon);targets.fog.set(w.fog);const badge=document.querySelector('#weather-status');if(badge)badge.textContent=w.name;}
 const mix=1-Math.exp(-Math.max(.016,dt)*.8);skyMat.uniforms.top.value.lerp(targets.top,mix);skyMat.uniforms.horizon.value.lerp(targets.horizon,mix);sky.position.copy(camera.position);if(scene.fog){scene.fog.color.lerp(targets.fog,mix);scene.fog.near+=(w.start-scene.fog.near)*mix;scene.fog.far+=(w.end-scene.fog.far)*mix;}sun.intensity+=(w.sun-sun.intensity)*mix;if(hemi)hemi.intensity+=(w.ambient-hemi.intensity)*mix;
 cloudMat.opacity+=(w.cloud*.8-cloudMat.opacity)*mix;cloudMat.color.set(type==='storm'?'#899ba2':type==='rain'?'#c0cbd0':'#f5f4e8');for(let i=0;i<seed.length;i++){const c=seed[i];dummy.position.set(((c.x+elapsed*w.wind+280)%560)-280,c.y,c.z);dummy.scale.set(c.scale*1.8,c.scale*.38,c.scale);dummy.rotation.set(0,i*.7,0);dummy.updateMatrix();clouds.setMatrixAt(i,dummy.matrix);}clouds.instanceMatrix.needsUpdate=true;
 rain.visible=w.rain>0;rain.position.set(focus.x,0,focus.z);if(rain.visible){for(let i=0;i<count;i++){positions[i*3+1]-=dt*(type==='storm'?30:21);positions[i*3]+=dt*w.wind;if(positions[i*3+1]<.2){positions[i*3+1]=40;positions[i*3]=(i*17.3%70)-35;}if(positions[i*3]>35)positions[i*3]=-35;}rainGeo.attributes.position.needsUpdate=true;}
 },get type(){return kind;}};
}
